from six import with_metaclass
from abc import ABCMeta
from taf.sw.dcap.rd.schemas.cm.gnb_enb_profile_v1 import GnbEnbProfileCMV1
from taf.sw.dcap.rd.schemas.cm.trace_profile_info_v1 import TraceProfileInfoCMV1
from taf.sw.dcap.rd.schemas.cm.tracers_v1 import TracersCMV1
from taf.sw.dcap.rd.auth.authorization import TokenProvider


class DCAP(with_metaclass(ABCMeta, object)):

    @property
    def cm(self):
        raise NotImplementedError

    @TokenProvider.provide_access_token
    def create_bts(self, host, port, username, password, bts_alias, credential_region_Id, timeout):
        return self.cm.create_bts(host, port, username, password, bts_alias, credential_region_Id, timeout)

    @TokenProvider.provide_access_token
    def create_multiple_bts(self, bts_info, timeout):
        return self.cm.create_multiple_bts(bts_info, timeout)

    @TokenProvider.provide_access_token
    def stop_trace(self, trace_id, timeout):
        return self.cm.stop_trace(trace_id=trace_id, timeout=timeout)

    @TokenProvider.provide_access_token
    def get_results(self, timeout=100, result_id=None, target_dir=None, target_file_name=None):
        return self.cm.get_results(result_id=result_id, target_dir=target_dir, target_file_name=target_file_name,
                                   timeout=timeout)

    @TokenProvider.provide_access_token
    def get_result_file_contents(self, result_id=None, timeout=100):
        return self.cm.get_result_file_contents(result_id=result_id, timeout=timeout)

    @TokenProvider.provide_access_token
    def get_result_file(self, file_path_in_zip, result_id=None, target_dir=None, target_file_name=None, timeout=100):
        return self.cm.get_result_file(file_path_in_zip=file_path_in_zip, result_id=result_id, target_dir=target_dir,
                                       target_file_name=target_file_name, timeout=timeout)

    @TokenProvider.provide_access_token
    def delete_bts(self, bts_id, timeout):
        return self.cm.delete_bts(bts_id=bts_id, timeout=timeout)

    @TokenProvider.provide_access_token
    def get_all_bts_info(self, timeout):
        return self.cm.get_all_bts_info(timeout=timeout)

    @TokenProvider.provide_access_token
    def get_bts_by_id(self, bts_id, timeout):
        return self.cm.get_bts_by_id(bts_id=bts_id, timeout=timeout)

    @TokenProvider.provide_access_token
    def get_trace_info_by_id(self, trace_id, timeout):
        trace_profile_info = self.cm.get_trace_info_by_id(trace_id=trace_id, timeout=timeout)
        return TraceProfileInfoCMV1.from_object_dict(trace_profile_info)

    @TokenProvider.provide_access_token
    def get_all_trace_info(self, timeout):
        return self.cm.get_all_trace_info(timeout=timeout)

    @TokenProvider.provide_access_token
    def get_5g_profiles(self, timeout):
        gnb_profile_info = self.cm.get_5g_profiles(timeout=timeout)
        return list(map(GnbEnbProfileCMV1.from_object_dict, gnb_profile_info))

    @TokenProvider.provide_access_token
    def get_lte_profiles(self, timeout):
        lte_profile_info = self.cm.get_lte_profiles(timeout=timeout)
        return list(map(GnbEnbProfileCMV1.from_object_dict, lte_profile_info))

    @TokenProvider.provide_access_token
    def edit_bts(self, bts_id, host, port='443', username='Nemuadmin', password='nemuuser', bts_alias='test_run',
                 lte_cells=None, nr_cells=None, timeout=30):
        return self.cm.edit_bts(bts_id=bts_id, host=host, port=port, username=username, password=password,
                                bts_alias=bts_alias, lte_cells=lte_cells, nr_cells=nr_cells, timeout=timeout)

    @TokenProvider.provide_access_token
    def delete_trace(self, trace_id, timeout):
        return self.cm.delete_trace(trace_id=trace_id, timeout=timeout)

    @TokenProvider.provide_access_token
    def get_tracers(self, timeout):
        tracers_info = self.cm.get_tracers(timeout=timeout)
        return list(map(TracersCMV1.from_object_dict, tracers_info))

    @TokenProvider.provide_access_token
    def get_bts_profiles(self, timeout):
        bts_profile_info = self.cm.get_bts_profiles(timeout=timeout)
        return list(map(GnbEnbProfileCMV1.from_object_dict, bts_profile_info))

    @TokenProvider.provide_access_token
    def abort_trace(self, trace_id, timeout):
        return self.cm.abort_trace(trace_id=trace_id, timeout=timeout)

    @TokenProvider.provide_access_token
    def get_vcu_profiles(self, timeout):
        vcu_profile_info = self.cm.get_vcu_profiles(timeout=timeout)
        return list(map(GnbEnbProfileCMV1.from_object_dict, vcu_profile_info))

    @TokenProvider.provide_access_token
    def get_vdu_profiles(self, timeout):
        vdu_profile_info = self.cm.get_vdu_profiles(timeout=timeout)
        return list(map(GnbEnbProfileCMV1.from_object_dict, vdu_profile_info))
